import { Routes, Route } from "react-router-dom";
import StartQuiz from "./component/StartQuiz";
import { useEffect, useState } from "react";
// import Quiz from "./component/Quiz";



function App() {
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState("");
    const [quizzes, setQuizzes] = useState([]);
    const [current, setCurrent] = useState(0);
    const [score, setScore] = useState(0);
    const [finished, setFinished] = useState(false);
    const loadQuestions = async () => {
        try {
            setLoading(true);
            setError("");

            const res = await fetch("/quizList.json", { cache: "no-store" });

            if (!res.ok) {
                throw new Error(`HTTP ${res.status} – nie można pobrać danych`);
            }

            const data = await res.json();

            validateQuizData(data);
            setQuizzes(data);
            setCurrent(0);
            setScore(0);
            setFinished(false);
        } catch (err) {
            setError(err.message || "Błąd podczas wczytywania danych");
        } finally {
            setLoading(false);
        }
    };

useEffect(() => {
  loadQuestions();
}, []);


    return (
    <Routes>
      <Route path="/" element={<StartQuiz listQuiz={quizzes} />} />
      {/* <Route path="/quiz/:id" element={<Quiz quizzes={quizzes} />} /> */}
    </Routes>
  );
}

export default App;
